css:
@import url("https://fonts.googleapis.com/css2?family=Monoton&family=Golos+Text:wght@400;500;700&display=swap");
:root{--dp:#1A0B2E;--dp2:#26123F;--dp3:#3A1E5C;--pk:#FF2E88;--cy:#00E5FF;--tx:#F2EAFB;--mu:#B6A6CC;--h:"Monoton",Impact,sans-serif;--b:"Golos Text",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.6;color:var(--tx);background:var(--dp)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{margin:0;line-height:1}h1,h2{font-family:var(--h);font-weight:400}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--cy);color:#000;padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--cy);outline-offset:3px}
.nav{display:flex;justify-content:space-between;align-items:center;height:76px;position:relative}.logo{font-weight:700;text-decoration:none;font-size:19px}.logo span{color:var(--pk)}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none}.menu a:hover{color:var(--cy)}.burger{display:none;background:none;border:2px solid var(--tx);color:var(--tx);width:44px;height:40px;font-size:20px;cursor:pointer}
.hero{position:relative;overflow:hidden;min-height:620px;display:flex;align-items:flex-end}.hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.45}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,var(--dp) 5%,transparent 70%)}
.hc{position:relative;z-index:2;padding:60px 0}.date{display:inline-block;border:2px solid var(--cy);color:var(--cy);border-radius:40px;padding:6px 16px;font-weight:700;margin-bottom:20px}
.hero h1{font-size:clamp(54px,9vw,130px);color:#fff;text-shadow:0 0 30px rgba(255,46,136,.6)}.hero p{font-size:20px;color:var(--mu);max-width:32em;margin:18px 0 24px}
.cd{display:flex;gap:10px;flex-wrap:wrap}.cd div{background:rgba(26,11,46,.8);border:1px solid var(--dp3);border-radius:14px;padding:10px 14px;text-align:center;min-width:80px}.cd b{display:block;font-size:30px;color:var(--pk)}.cd span{font-size:13px;color:var(--mu)}
.btn{display:inline-block;background:var(--pk);color:#fff;text-decoration:none;font:700 17px var(--b);padding:14px 26px;border-radius:40px;border:0;cursor:pointer}
section{padding:80px 0}.sh h2{font-size:clamp(38px,5vw,66px);color:var(--cy);margin-bottom:12px}.sh p{color:var(--mu);margin:0 0 30px;max-width:34em}
.lu{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.act{border:1px solid var(--dp3);border-radius:18px;padding:22px;background:var(--dp2)}.act .t{color:var(--pk);font-weight:700}.act h3{font-size:30px;margin:8px 0 6px;font-weight:700}.act p{margin:0;color:var(--mu);font-size:15px}.act.head{grid-column:span 3;background:linear-gradient(120deg,var(--dp3),var(--dp2))}.act.head h3{font-size:clamp(34px,5vw,56px)}
.tx .g{display:grid;grid-template-columns:1.2fr .8fr;gap:30px;align-items:start}.tx .g>div{min-width:0}
.tier{display:grid;grid-template-columns:1fr auto;gap:10px 20px;align-items:center;border:1px solid var(--dp3);border-radius:18px;padding:20px;margin-bottom:12px;background:var(--dp2)}.tier h3{font-size:22px}.tier p{margin:4px 0 0;color:var(--mu);font-size:15px}.tier .pr{font-size:26px;font-weight:700;color:var(--cy)}
.tier.so{opacity:.55}.tier .left{font-size:13px;color:var(--pk);font-weight:700}
.qt{display:flex;align-items:center;gap:10px;grid-column:2}.qt button{width:40px;height:40px;border-radius:50%;border:2px solid var(--cy);background:transparent;color:var(--cy);font-size:20px;cursor:pointer}.qt button:disabled{opacity:.35;cursor:not-allowed}.qt output{font-weight:700;font-size:20px;min-width:22px;text-align:center}
.sum{background:var(--tx);color:var(--dp);border-radius:22px;padding:24px;position:sticky;top:16px}.sum h3{font-size:24px}.sum ul{list-style:none;padding:0;margin:14px 0}.sum li{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px dashed #CBBFDA;font-size:15px}
.promo{display:flex;gap:8px;margin:8px 0 4px}.promo input{flex:1;min-width:0;font:16px var(--b);padding:10px 12px;border:1px solid #CBBFDA;border-radius:10px}.promo button{font:700 15px var(--b);background:var(--dp);color:#fff;border:0;border-radius:10px;padding:0 14px;cursor:pointer}.promo label{position:absolute;left:-999px}
.pm{font-size:14px;min-height:20px;margin:0 0 8px}.tot{display:flex;justify-content:space-between;align-items:baseline;margin:10px 0 14px}.tot b{font-size:38px}
.sum .btn{width:100%;text-align:center}.sum .btn:disabled{opacity:.5;cursor:not-allowed}.msg{visibility:hidden;margin:10px 0 0;font-weight:700;color:#B0126A;font-size:15px}.msg.on{visibility:visible}
.info .g2{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.info h3{font-size:22px;color:var(--pk);margin-bottom:8px}.info p{margin:0;color:var(--mu)}
footer{border-top:1px solid var(--dp3);padding:26px 0;font-size:15px;color:var(--mu)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:960px){.tx .g{grid-template-columns:minmax(0,1fr)}.tx .g>*{min-width:0}.sum{position:static}.lu{grid-template-columns:1fr 1fr}.act.head{grid-column:span 2}.info .g2{grid-template-columns:1fr}}
.tier>div{min-width:0}
@media (max-width:760px){.tier{grid-template-columns:1fr auto;padding:16px}.qt{grid-column:1/-1}.burger{display:block}.menu{display:none;position:absolute;top:76px;left:0;right:0;background:var(--dp2);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.lu{grid-template-columns:1fr}.act.head{grid-column:span 1}.cd div{min-width:68px}}

