(()=>{const $=id=>document.getElementById(id);const D=new Date('2026-11-14T18:00:00');
function cd(){const s=Math.max(0,Math.floor((D-new Date())/1000));$('cD').textContent=Math.floor(s/86400);$('cH').textContent=Math.floor(s%86400/3600);$('cM').textContent=Math.floor(s%3600/60)}cd();setInterval(cd,30000);
const T=[["Early bird","General entry, limited release",29,0,0],["General admission","Entry from 6pm, standing",39,120,0],["Front of stage","Own area near the stage, fast lane entry",65,18,0],["VIP deck","Raised deck, 2 drinks, private bar and toilets",110,6,0]];let promo=0;
function tiers(){const tot=T.reduce((a,t)=>a+t[4],0);$('tiers').innerHTML=T.map((t,i)=>{const so=t[3]===0;return`<div class="tier${so?' so':''}"><div><h3>${t[0]}</h3><p>${t[1]}</p>${so?'<span class="left">Sold out</span>':t[3]<20?`<span class="left">Only ${t[3]} left</span>`:''}</div><span class="pr">$${t[2]}</span><div class="qt" role="group" aria-label="${t[0]} tickets"><button type="button" data-i="${i}" data-d="-1" aria-label="Remove one" ${t[4]===0?'disabled':''}>−</button><output>${t[4]}</output><button type="button" data-i="${i}" data-d="1" aria-label="Add one" ${so||tot>=8||t[4]>=t[3]?'disabled':''}>+</button></div></div>`}).join('');sum()}
function sum(){const L=T.filter(t=>t[4]).map(t=>[`${t[4]} x ${t[0]}`,t[4]*t[2]]);const sub=L.reduce((a,l)=>a+l[1],0),n=T.reduce((a,t)=>a+t[4],0),fee=n*3.5,disc=sub*promo;
$('sl').innerHTML=L.length?L.map(l=>`<li><span>${l[0]}</span><span>$${l[1]}</span></li>`).join('')+`<li><span>Booking fee ($3.50 each)</span><span>$${fee.toFixed(2)}</span></li>`+(promo?`<li><span>Promo discount</span><span>−$${disc.toFixed(2)}</span></li>`:''):'<li><span>No tickets yet</span><span></span></li>';
const t=sub+fee-disc;$('tt').textContent='$'+(t%1?t.toFixed(2):t);$('buy').disabled=!n}
$('tiers').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const t=T[+b.dataset.i];t[4]=Math.max(0,t[4]+ +b.dataset.d);tiers()};
$('pa').onclick=()=>{const c=$('pc').value.trim().toUpperCase();if(c==='ARCHES10'){promo=.1;$('pm').textContent='Code applied: 10% off tickets.'}else{promo=0;$('pm').textContent=c?'That code is not valid. Try ARCHES10.':''}sum()};
$('buy').onclick=()=>{$('msg').textContent='In your own site, this button would open your ticket checkout.';$('msg').classList.add('on')};T[1][4]=2;tiers();
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
